export const QUESTIONS = prompts.map(([axis, direction, kind, title, text, optionA, optionB, rationale], i) => ({id: i + 1, axis, direction, kind, title, text, optionA, optionB, rationale}));
export function getQuestions(length) {
  if (![30, 50].includes(length)) throw new RangeError('Unsupported questionnaire length');
  return QUESTIONS.slice(0, length);
}
